namespace Application.DictionaryImport;

/// <summary>Replay inputs; review references are operator evidence, never generated by the importer.</summary>
public sealed record DictionarySourceLock
{
    public int SchemaVersion { get; init; } = 1;
    // Older source locks retain the original four-component scope unless explicitly changed.
    public string Scope { get; init; } = "ja-vi";
    public string TransformationId { get; init; } = "";
    public string TransformationSha256 { get; init; } = "";
    public string MappingPath { get; init; } = "";
    public string MappingSha256 { get; init; } = "";
    public string MappingApprovalReference { get; init; } = "";
    public IReadOnlyList<DictionarySourcePin> Sources { get; init; } = [];
}

public sealed record DictionarySourcePin
{
    public string SourceId { get; init; } = "";
    public string Kind { get; init; } = "";
    public string Publisher { get; init; } = "";
    public string Version { get; init; } = "";
    public string ArtifactUrl { get; init; } = "";
    public string ArtifactPath { get; init; } = "";
    public string Compression { get; init; } = "none";
    public long ArtifactBytes { get; init; }
    public string ArtifactSha256 { get; init; } = "";
    public string ExpandedSha256 { get; init; } = "";
    public long ExpandedBytes { get; init; }
    public long MaxExpandedBytes { get; init; }
    public long ExpectedRecords { get; init; }
    public string SchemaPath { get; init; } = "";
    public string SchemaSha256 { get; init; } = "";
    public IReadOnlyDictionary<string, string> SchemaEntities { get; init; } = new Dictionary<string, string>();
    public string LicensePath { get; init; } = "";
    public string LicenseSha256 { get; init; } = "";
    public string LicenseStatus { get; init; } = "pending";
    public string LicenseApprovalReference { get; init; } = "";
    public string Attribution { get; init; } = "";
}

public sealed record ImportBlocker(string ErrorCode, string Message, string? SourceId = null);

public sealed record SourceLockInspection(
    DictionarySourceLock? Lock,
    string SourceLockSha256,
    string FingerprintSha256,
    IReadOnlyList<ImportBlocker> Blockers)
{
    public bool IsReady => Lock is not null && Blockers.Count == 0;
}

public sealed record DictionaryImportInvocation(string Verb, string SourceLockPath, string? RunId, string? ConfirmTarget, int BatchSize = 500);

public sealed record DictionaryImportCommandResult(int ExitCode, object Report);
